}

import { redirect } from "react-router";
import { z } from "zod";
import type { Route } from "./+types/api.set-dev-country";
import { setDevCountry } from "~/lib/session";
import { parseFormData } from "~/lib/validation";

const setDevCountrySchema = z.object({
  country: z.string().length(2).or(z.literal("")).transform((v) => v || null),
});

export async function action({ request }: Route.ActionArgs) {
  const formData = await request.formData();
  const parsed = parseFormData(formData, setDevCountrySchema);

  const country = parsed.success ? parsed.data.country : null;

  const cookie = await setDevCountry(request, country);

  return redirect(new URL(request.url).searchParams.get("redirectTo") ?? "/", {
    headers: { "Set-Cookie": cookie },
  });
}

import { eq, and, sql } from "drizzle-orm";
import { db } from "~/db";
import {
  enrollments,
  courses,
  modules,
  lessons,
  lessonProgress,
  LessonProgressStatus,
} from "~/db/schema";

// ─── Enrollment Service ───
// Handles enrollment, unenrollment, duplicate prevention, and enrollment validation.
// Uses positional parameters (project convention).

export function getEnrollmentById(id: number) {
  return db.select().from(enrollments).where(eq(enrollments.id, id)).get();
}

export function getEnrollmentsByUser(userId: number) {
  return db
    .select()
    .from(enrollments)
    .where(eq(enrollments.userId, userId))
    .all();
}

export function getEnrollmentsByCourse(courseId: number) {
  return db
    .select()
    .from(enrollments)
    .where(eq(enrollments.courseId, courseId))
    .all();
}

export function getEnrollmentCountForCourse(courseId: number) {
  const result = db
    .select({ count: sql<number>`count(*)` })
    .from(enrollments)
    .where(eq(enrollments.courseId, courseId))
    .get();

  return result?.count ?? 0;
}

export function findEnrollment(userId: number, courseId: number) {
  return db
    .select()
    .from(enrollments)
    .where(
      and(eq(enrollments.userId, userId), eq(enrollments.courseId, courseId))
    )
    .get();
}

export function isUserEnrolled(userId: number, courseId: number) {
  return !!findEnrollment(userId, courseId);
}

export function enrollUser(
  userId: number,
  courseId: number,
  sendEmail: boolean,
  skipValidation: boolean
) {
  if (!skipValidation) {
    // Check if already enrolled
    const existing = findEnrollment(userId, courseId);
    if (existing) {
      throw new Error("User is already enrolled in this course");
    }

    // Check that the course exists
    const course = db
      .select()
      .from(courses)
      .where(eq(courses.id, courseId))
      .get();
    if (!course) {
      throw new Error("Course not found");
    }
  }

  const enrollment = db
    .insert(enrollments)
    .values({ userId, courseId })
    .returning()
    .get();

  // sendEmail parameter accepted but not implemented (no email service — PRD out of scope)
  if (sendEmail) {
    // Would send welcome email here
  }

  return enrollment;
}

export function unenrollUser(userId: number, courseId: number) {
  const existing = findEnrollment(userId, courseId);
  if (!existing) {
    throw new Error("User is not enrolled in this course");
  }

  return db
    .delete(enrollments)
    .where(
      and(eq(enrollments.userId, userId), eq(enrollments.courseId, courseId))
    )
    .returning()
    .get();
}

export function markEnrollmentComplete(userId: number, courseId: number) {
  return db
    .update(enrollments)
    .set({ completedAt: new Date().toISOString() })
    .where(
      and(eq(enrollments.userId, userId), eq(enrollments.courseId, courseId))
    )
    .returning()
    .get();
}

export function getUserEnrolledCourses(userId: number) {
  return db
    .select({
      enrollmentId: enrollments.id,
      courseId: enrollments.courseId,
      enrolledAt: enrollments.enrolledAt,
      completedAt: enrollments.completedAt,
      courseTitle: courses.title,
      courseSlug: courses.slug,
      courseDescription: courses.description,
      coverImageUrl: courses.coverImageUrl,
    })
    .from(enrollments)
    .innerJoin(courses, eq(enrollments.courseId, courses.id))
    .where(eq(enrollments.userId, userId))
    .all();
}

export function getCourseEnrolledStudents(courseId: number) {
  return db
    .select({
      enrollmentId: enrollments.id,
      userId: enrollments.userId,
      enrolledAt: enrollments.enrolledAt,
      completedAt: enrollments.completedAt,
    })
    .from(enrollments)
    .where(eq(enrollments.courseId, courseId))
    .all();
}

import { defineConfig } from "vitest/config";
import tsconfigPaths from "vite-tsconfig-paths";

export default defineConfig({
  plugins: [tsconfigPaths()],
  test: {
    globals: true,
  },
});

import { describe, it, expect, vi, beforeEach } from "vitest";

// Mock the session module
const mockSession = new Map<string, string>();
vi.mock("~/lib/session", () => ({
  getSession: vi.fn(async () => ({
    get: (key: string) => mockSession.get(key),
  })),
}));

// Mock global fetch for ip-api.com
const mockFetch = vi.fn();
vi.stubGlobal("fetch", mockFetch);

import { resolveCountry } from "./country.server";

function makeRequest(headers: Record<string, string> = {}): Request {
  return new Request("http://localhost:3000", { headers });
}

describe("resolveCountry", () => {
  beforeEach(() => {
    mockSession.clear();
    mockFetch.mockReset();
  });

  // ─── Priority Ordering ───

  it("uses dev session override first", async () => {
    mockSession.set("devCountry", "IN");
    const result = await resolveCountry(
      makeRequest({ "CF-IPCountry": "US", "X-Forwarded-For": "1.2.3.4" }),
    );
    expect(result).toBe("IN");
  });

  it("falls back to CF-IPCountry when no dev override", async () => {
    const result = await resolveCountry(makeRequest({ "CF-IPCountry": "BR" }));
    expect(result).toBe("BR");
  });

  it("falls back to ip-api.com when no dev override and no CF header", async () => {
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ countryCode: "NG" }),
    });
    const result = await resolveCountry(
      makeRequest({ "X-Forwarded-For": "1.2.3.4" }),
    );
    expect(result).toBe("NG");
    expect(mockFetch).toHaveBeenCalledWith(
      "http://ip-api.com/json/1.2.3.4?fields=countryCode",
    );
  });

  it("returns null when all methods fail", async () => {
    const result = await resolveCountry(makeRequest());
    expect(result).toBeNull();
  });

  // ─── Dev Override Behavior ───

  it("normalizes dev country to uppercase", async () => {
    mockSession.set("devCountry", "pl");
    const result = await resolveCountry(makeRequest());
    expect(result).toBe("PL");
  });

  it("ignores dev country if not exactly 2 characters", async () => {
    mockSession.set("devCountry", "USA");
    const result = await resolveCountry(makeRequest());
    expect(result).toBeNull();
  });

  // ─── CF-IPCountry Behavior ───

  it("normalizes CF-IPCountry to uppercase", async () => {
    const result = await resolveCountry(makeRequest({ "CF-IPCountry": "de" }));
    expect(result).toBe("DE");
  });

  it("ignores CF-IPCountry when value is XX", async () => {
    const result = await resolveCountry(makeRequest({ "CF-IPCountry": "XX" }));
    expect(result).toBeNull();
  });

  // ─── ip-api.com Behavior ───

  it("uses first IP from X-Forwarded-For", async () => {
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ countryCode: "JP" }),
    });
    await resolveCountry(
      makeRequest({ "X-Forwarded-For": "1.2.3.4, 5.6.7.8" }),
    );
    expect(mockFetch).toHaveBeenCalledWith(
      "http://ip-api.com/json/1.2.3.4?fields=countryCode",
    );
  });

  it("returns null when ip-api.com returns non-ok response", async () => {
    mockFetch.mockResolvedValueOnce({ ok: false });
    const result = await resolveCountry(
      makeRequest({ "X-Forwarded-For": "1.2.3.4" }),
    );
    expect(result).toBeNull();
  });

  it("returns null when ip-api.com throws (network error)", async () => {
    mockFetch.mockRejectedValueOnce(new Error("network error"));
    const result = await resolveCountry(
      makeRequest({ "X-Forwarded-For": "1.2.3.4" }),
    );
    expect(result).toBeNull();
  });

  it("returns null when ip-api.com returns no countryCode", async () => {
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ status: "fail" }),
    });
    const result = await resolveCountry(
      makeRequest({ "X-Forwarded-For": "1.2.3.4" }),
    );
    expect(result).toBeNull();
  });

  it("skips ip-api.com when no X-Forwarded-For header", async () => {
    const result = await resolveCountry(makeRequest());
    expect(mockFetch).not.toHaveBeenCalled();
    expect(result).toBeNull();
  });
});

import { describe, it, expect } from "vitest";
import {
  getTierForCountry,
  getDiscountForCountry,
  calculatePppPrice,
  getCountryTierInfo,
  checkPppAccess,
} from "./ppp";

describe("PPP Config", () => {
  // ─── Tier Mapping ───

  describe("getTierForCountry", () => {
    it("returns tier 1 for US", () => {
      expect(getTierForCountry("US")).toBe(1);
    });

    it("returns tier 2 for Poland", () => {
      expect(getTierForCountry("PL")).toBe(2);
    });

    it("returns tier 3 for India", () => {
      expect(getTierForCountry("IN")).toBe(3);
    });

    it("returns tier 4 for Nigeria", () => {
      expect(getTierForCountry("NG")).toBe(4);
    });

    it("returns tier 1 for unmapped countries", () => {
      expect(getTierForCountry("XX")).toBe(1);
      expect(getTierForCountry("ZZ")).toBe(1);
    });

    it("returns tier 1 for null", () => {
      expect(getTierForCountry(null)).toBe(1);
    });

    it("is case-insensitive", () => {
      expect(getTierForCountry("in")).toBe(3);
      expect(getTierForCountry("Us")).toBe(1);
    });
  });

  // ─── Discount ───

  describe("getDiscountForCountry", () => {
    it("returns 0 for tier 1 countries", () => {
      expect(getDiscountForCountry("US")).toBe(0);
    });

    it("returns 0.3 for tier 2 countries", () => {
      expect(getDiscountForCountry("BR")).toBe(0.3);
    });

    it("returns 0.5 for tier 3 countries", () => {
      expect(getDiscountForCountry("IN")).toBe(0.5);
    });

    it("returns 0.7 for tier 4 countries", () => {
      expect(getDiscountForCountry("NG")).toBe(0.7);
    });

    it("returns 0 for null country", () => {
      expect(getDiscountForCountry(null)).toBe(0);
    });
  });

  // ─── Price Calculation ───

  describe("calculatePppPrice", () => {
    it("returns full price for tier 1", () => {
      expect(calculatePppPrice(4999, "US")).toBe(4999);
    });

    it("applies 30% discount for tier 2", () => {
      expect(calculatePppPrice(4999, "BR")).toBe(3499);
    });

    it("applies 50% discount for tier 3", () => {
      expect(calculatePppPrice(4999, "IN")).toBe(2500);
    });

    it("applies 70% discount for tier 4", () => {
      expect(calculatePppPrice(4999, "NG")).toBe(1500);
    });

    it("returns 0 for free courses", () => {
      expect(calculatePppPrice(0, "IN")).toBe(0);
    });

    it("returns full price for null country", () => {
      expect(calculatePppPrice(4999, null)).toBe(4999);
    });
  });

  // ─── Tier Info ───

  describe("getCountryTierInfo", () => {
    it("returns tier, discount, and label", () => {
      const info = getCountryTierInfo("IN");
      expect(info).toEqual({ tier: 3, discount: 0.5, label: "50% off" });
    });

    it("returns full price info for null", () => {
      const info = getCountryTierInfo(null);
      expect(info).toEqual({ tier: 1, discount: 0, label: "Full Price" });
    });
  });

  // ─── PPP Access Guard ───

  describe("checkPppAccess", () => {
    // --- Free courses are never blocked ---

    it("allows access to free courses regardless of country", () => {
      const result = checkPppAccess(0, true, "IN", "US");
      expect(result.blocked).toBe(false);
    });

    // --- PPP-disabled courses are never blocked ---

    it("allows access when PPP is disabled on course", () => {
      const result = checkPppAccess(4999, false, "IN", "US");
      expect(result.blocked).toBe(false);
    });

    // --- No purchase country recorded ---

    it("allows access when purchase country is null", () => {
      const result = checkPppAccess(4999, true, null, "US");
      expect(result.blocked).toBe(false);
    });

    // --- Tier 1 (full price) purchases are never blocked ---

    it("allows Tier 1 purchase from any country", () => {
      const result = checkPppAccess(4999, true, "US", "IN");
      expect(result.blocked).toBe(false);
    });

    it("allows Tier 1 purchase when current country is null", () => {
      const result = checkPppAccess(4999, true, "US", null);
      expect(result.blocked).toBe(false);
    });

    // --- Discounted purchase — matching country ---

    it("allows Tier 2 purchase when country matches", () => {
      const result = checkPppAccess(4999, true, "PL", "PL");
      expect(result.blocked).toBe(false);
    });

    it("allows Tier 3 purchase when country matches", () => {
      const result = checkPppAccess(4999, true, "IN", "IN");
      expect(result.blocked).toBe(false);
    });

    it("allows Tier 4 purchase when country matches", () => {
      const result = checkPppAccess(4999, true, "NG", "NG");
      expect(result.blocked).toBe(false);
    });

    // --- Discounted purchase — mismatching country ---

    it("blocks Tier 2 purchase when accessed from different country", () => {
      const result = checkPppAccess(4999, true, "PL", "DE");
      expect(result.blocked).toBe(true);
      expect(result.blockedCountry).toBe("DE");
      expect(result.purchaseCountry).toBe("PL");
    });

    it("blocks Tier 3 purchase when accessed from different country", () => {
      const result = checkPppAccess(4999, true, "IN", "US");
      expect(result.blocked).toBe(true);
      expect(result.blockedCountry).toBe("US");
      expect(result.purchaseCountry).toBe("IN");
    });

    it("blocks Tier 4 purchase when accessed from different country", () => {
      const result = checkPppAccess(4999, true, "NG", "GB");
      expect(result.blocked).toBe(true);
      expect(result.blockedCountry).toBe("GB");
      expect(result.purchaseCountry).toBe("NG");
    });

    // --- Discounted purchase — current country unknown ---

    it("allows discounted purchase when current country is null", () => {
      const result = checkPppAccess(4999, true, "IN", null);
      expect(result.blocked).toBe(false);
    });

    // --- Return value shape ---

    it("returns null fields when not blocked", () => {
      const result = checkPppAccess(4999, true, "US", "IN");
      expect(result).toEqual({
        blocked: false,
        blockedCountry: null,
        purchaseCountry: null,
      });
    });

    it("returns country details when blocked", () => {
      const result = checkPppAccess(4999, true, "IN", "US");
      expect(result).toEqual({
        blocked: true,
        blockedCountry: "US",
        purchaseCountry: "IN",
      });
    });
  });
});

import { describe, it, expect, beforeEach, vi } from "vitest";
import { createTestDb, seedBaseData } from "~/test/setup";
import * as schema from "~/db/schema";

let testDb: ReturnType<typeof createTestDb>;
let base: ReturnType<typeof seedBaseData>;

vi.mock("~/db", () => ({
  get db() {
    return testDb;
  },
}));

// Import after mock so the module picks up our test db
import {
  getLessonById,
  getLessonsByModule,
  getLessonCount,
  createLesson,
  updateLesson,
  updateLessonTitle,
  updateLessonContent,
  deleteLesson,
  moveLessonToPosition,
  swapLessonPositions,
  reorderLessons,
} from "./lessonService";
import { createModule } from "./moduleService";

let moduleId: number;

describe("lessonService", () => {
  beforeEach(() => {
    testDb = createTestDb();
    base = seedBaseData(testDb);
    // Create a module to hold lessons
    const mod = createModule(base.course.id, "Test Module", 1);
    moduleId = mod.id;
  });

  // ─── CRUD ───

  describe("createLesson", () => {
    it("creates a lesson with explicit position", () => {
      const lesson = createLesson(moduleId, "Lesson 1", "Some content", null, 1, 30);

      expect(lesson).toBeDefined();
      expect(lesson.title).toBe("Lesson 1");
      expect(lesson.moduleId).toBe(moduleId);
      expect(lesson.content).toBe("Some content");
      expect(lesson.position).toBe(1);
      expect(lesson.durationMinutes).toBe(30);
    });

    it("auto-calculates position when null", () => {
      createLesson(moduleId, "Lesson 1", null, null, null, null);
      const l2 = createLesson(moduleId, "Lesson 2", null, null, null, null);

      expect(l2.position).toBe(2);
    });

    it("starts auto position at 1 for empty module", () => {
      const lesson = createLesson(moduleId, "First", null, null, null, null);

      expect(lesson.position).toBe(1);
    });

    it("creates a lesson with video URL", () => {
      const lesson = createLesson(
        moduleId,
        "Video Lesson",
        null,
        "https://youtube.com/watch?v=abc123",
        1,
        null
      );

      expect(lesson.videoUrl).toBe("https://youtube.com/watch?v=abc123");
    });
  });

  describe("getLessonById", () => {
    it("returns a lesson by id", () => {
      const created = createLesson(moduleId, "Find Me", null, null, 1, null);

      const found = getLessonById(created.id);
      expect(found).toBeDefined();
      expect(found!.title).toBe("Find Me");
    });

    it("returns undefined for non-existent id", () => {
      expect(getLessonById(9999)).toBeUndefined();
    });
  });

  describe("getLessonsByModule", () => {
    it("returns lessons ordered by position", () => {
      createLesson(moduleId, "Third", null, null, 3, null);
      createLesson(moduleId, "First", null, null, 1, null);
      createLesson(moduleId, "Second", null, null, 2, null);

      const lessons = getLessonsByModule(moduleId);
      expect(lessons).toHaveLength(3);
      expect(lessons[0].title).toBe("First");
      expect(lessons[1].title).toBe("Second");
      expect(lessons[2].title).toBe("Third");
    });

    it("returns empty array for module with no lessons", () => {
      expect(getLessonsByModule(moduleId)).toHaveLength(0);
    });
  });

  describe("getLessonCount", () => {
    it("returns the number of lessons in a module", () => {
      createLesson(moduleId, "L1", null, null, 1, null);
      createLesson(moduleId, "L2", null, null, 2, null);

      expect(getLessonCount(moduleId)).toBe(2);
    });

    it("returns 0 for module with no lessons", () => {
      expect(getLessonCount(moduleId)).toBe(0);
    });
  });

  describe("updateLesson", () => {
    it("updates title when provided", () => {
      const lesson = createLesson(moduleId, "Old", "old content", null, 1, 10);

      const updated = updateLesson(lesson.id, "New Title", null, null, null);
      expect(updated!.title).toBe("New Title");
      expect(updated!.content).toBe("old content"); // unchanged
    });

    it("updates content when provided", () => {
      const lesson = createLesson(moduleId, "Title", "old content", null, 1, null);

      const updated = updateLesson(lesson.id, null, "new content", null, null);
      expect(updated!.content).toBe("new content");
      expect(updated!.title).toBe("Title"); // unchanged
    });

    it("updates multiple fields at once", () => {
      const lesson = createLesson(moduleId, "Old", null, null, 1, null);

      const updated = updateLesson(lesson.id, "New", "some content", "https://yt.com", 45);
      expect(updated!.title).toBe("New");
      expect(updated!.content).toBe("some content");
      expect(updated!.videoUrl).toBe("https://yt.com");
      expect(updated!.durationMinutes).toBe(45);
    });

    it("returns lesson unchanged when all fields are null", () => {
      const lesson = createLesson(moduleId, "Same", "same content", null, 1, 10);

      const result = updateLesson(lesson.id, null, null, null, null);
      expect(result!.title).toBe("Same");
      expect(result!.content).toBe("same content");
    });
  });

  describe("updateLessonTitle", () => {
    it("updates just the title", () => {
      const lesson = createLesson(moduleId, "Old Title", null, null, 1, null);

      const updated = updateLessonTitle(lesson.id, "New Title");
      expect(updated!.title).toBe("New Title");
    });
  });

  describe("updateLessonContent", () => {
    it("updates just the content", () => {
      const lesson = createLesson(moduleId, "Title", "old content", null, 1, null);

      const updated = updateLessonContent(lesson.id, "new content");
      expect(updated!.content).toBe("new content");
    });
  });

  describe("deleteLesson", () => {
    it("deletes a lesson", () => {
      const lesson = createLesson(moduleId, "Delete Me", null, null, 1, null);

      const deleted = deleteLesson(lesson.id);
      expect(deleted).toBeDefined();
      expect(deleted!.id).toBe(lesson.id);

      expect(getLessonById(lesson.id)).toBeUndefined();
    });
  });

  // ─── Reordering ───

  describe("moveLessonToPosition", () => {
    it("moves a lesson down (position 1 → 3)", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 1, null);
      const l2 = createLesson(moduleId, "L2", null, null, 2, null);
      const l3 = createLesson(moduleId, "L3", null, null, 3, null);

      const moved = moveLessonToPosition(l1.id, 3);
      expect(moved!.position).toBe(3);

      const lessons = getLessonsByModule(moduleId);
      expect(lessons[0].title).toBe("L2");
      expect(lessons[0].position).toBe(1);
      expect(lessons[1].title).toBe("L3");
      expect(lessons[1].position).toBe(2);
      expect(lessons[2].title).toBe("L1");
      expect(lessons[2].position).toBe(3);
    });

    it("moves a lesson up (position 3 → 1)", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 1, null);
      const l2 = createLesson(moduleId, "L2", null, null, 2, null);
      const l3 = createLesson(moduleId, "L3", null, null, 3, null);

      const moved = moveLessonToPosition(l3.id, 1);
      expect(moved!.position).toBe(1);

      const lessons = getLessonsByModule(moduleId);
      expect(lessons[0].title).toBe("L3");
      expect(lessons[0].position).toBe(1);
      expect(lessons[1].title).toBe("L1");
      expect(lessons[1].position).toBe(2);
      expect(lessons[2].title).toBe("L2");
      expect(lessons[2].position).toBe(3);
    });

    it("returns lesson unchanged when moving to same position", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 1, null);

      const result = moveLessonToPosition(l1.id, 1);
      expect(result!.position).toBe(1);
    });

    it("returns null for non-existent lesson", () => {
      expect(moveLessonToPosition(9999, 1)).toBeNull();
    });

    it("moves a lesson to middle position (1 → 2 of 3)", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 1, null);
      const l2 = createLesson(moduleId, "L2", null, null, 2, null);
      const l3 = createLesson(moduleId, "L3", null, null, 3, null);

      moveLessonToPosition(l1.id, 2);

      const lessons = getLessonsByModule(moduleId);
      expect(lessons[0].title).toBe("L2");
      expect(lessons[0].position).toBe(1);
      expect(lessons[1].title).toBe("L1");
      expect(lessons[1].position).toBe(2);
      expect(lessons[2].title).toBe("L3");
      expect(lessons[2].position).toBe(3);
    });

    it("moves from middle to end (2 → 3 of 3)", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 1, null);
      const l2 = createLesson(moduleId, "L2", null, null, 2, null);
      const l3 = createLesson(moduleId, "L3", null, null, 3, null);

      moveLessonToPosition(l2.id, 3);

      const lessons = getLessonsByModule(moduleId);
      expect(lessons[0].title).toBe("L1");
      expect(lessons[0].position).toBe(1);
      expect(lessons[1].title).toBe("L3");
      expect(lessons[1].position).toBe(2);
      expect(lessons[2].title).toBe("L2");
      expect(lessons[2].position).toBe(3);
    });

    it("does not affect lessons in other modules", () => {
      const mod2 = createModule(base.course.id, "Module 2", 2);

      const l1 = createLesson(moduleId, "L1", null, null, 1, null);
      const l2 = createLesson(moduleId, "L2", null, null, 2, null);
      const other = createLesson(mod2.id, "Other L1", null, null, 1, null);

      moveLessonToPosition(l1.id, 2);

      // Other module's lesson should be untouched
      const otherLesson = getLessonById(other.id);
      expect(otherLesson!.position).toBe(1);
    });
  });

  describe("swapLessonPositions", () => {
    it("swaps positions of two lessons", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 1, null);
      const l2 = createLesson(moduleId, "L2", null, null, 2, null);

      const result = swapLessonPositions(l1.id, l2.id);
      expect(result).toBeDefined();
      expect(result!.a.position).toBe(2);
      expect(result!.b.position).toBe(1);

      const lessons = getLessonsByModule(moduleId);
      expect(lessons[0].title).toBe("L2");
      expect(lessons[1].title).toBe("L1");
    });

    it("swaps non-adjacent lessons", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 1, null);
      const l2 = createLesson(moduleId, "L2", null, null, 2, null);
      const l3 = createLesson(moduleId, "L3", null, null, 3, null);

      swapLessonPositions(l1.id, l3.id);

      const lessons = getLessonsByModule(moduleId);
      expect(lessons[0].title).toBe("L3");
      expect(lessons[0].position).toBe(1);
      expect(lessons[1].title).toBe("L2");
      expect(lessons[1].position).toBe(2);
      expect(lessons[2].title).toBe("L1");
      expect(lessons[2].position).toBe(3);
    });

    it("returns null when first lesson does not exist", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 1, null);

      expect(swapLessonPositions(9999, l1.id)).toBeNull();
    });

    it("returns null when second lesson does not exist", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 1, null);

      expect(swapLessonPositions(l1.id, 9999)).toBeNull();
    });
  });

  describe("reorderLessons", () => {
    it("reorders lessons according to the given id array", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 1, null);
      const l2 = createLesson(moduleId, "L2", null, null, 2, null);
      const l3 = createLesson(moduleId, "L3", null, null, 3, null);

      // Reverse the order: L3 → pos 1, L2 → pos 2, L1 → pos 3
      const result = reorderLessons(moduleId, [l3.id, l2.id, l1.id]);

      // Result is ordered by position (returned by getLessonsByModule)
      expect(result).toHaveLength(3);
      expect(result[0].title).toBe("L3");
      expect(result[0].position).toBe(1);
      expect(result[1].title).toBe("L2");
      expect(result[1].position).toBe(2);
      expect(result[2].title).toBe("L1");
      expect(result[2].position).toBe(3);
    });

    it("assigns positions starting at 1 and normalizes gaps", () => {
      const l1 = createLesson(moduleId, "L1", null, null, 10, null);
      const l2 = createLesson(moduleId, "L2", null, null, 20, null);

      reorderLessons(moduleId, [l2.id, l1.id]);

      const lessons = getLessonsByModule(moduleId);
      expect(lessons[0].position).toBe(1);
      expect(lessons[1].position).toBe(2);
    });

    it("does not reorder lessons from a different module", () => {
      const mod2 = createModule(base.course.id, "Module 2", 2);

      const l1 = createLesson(moduleId, "L1", null, null, 1, null);
      const other = createLesson(mod2.id, "Other", null, null, 1, null);

      // Try to include a lesson from another module
      reorderLessons(moduleId, [other.id, l1.id]);

      // Other module's lesson should be unchanged — moduleId filter prevents update
      const otherLesson = getLessonById(other.id);
      expect(otherLesson!.position).toBe(1);
    });
  });
});

